// Função abaixo está em CustomFunctions, retorna o nome atual da página. 

// O funcionamento desse botão depende intrínscicamente da definição do PageObject com 
// o nome IDÊNTICO ao retorno da função, atentar-se a isso ao implementar em outros locais.


const aditionalParamsNeeded = (param, table) => {
				return `&${param}=` + window[table].findItem( 'simple_grid_field', window[table].selectedId)['0'].innerText
}

const table = verifyCurrentPage(pageObj.tName)
const additionalParams = (table == 't_pack_layer')? aditionalParamsNeeded('fuid_pack', 't_pack') : ''

console.log(table)
const popup = Runner.displayPopup({
	url:(table) +  '_list.php?page=list_show_more' + additionalParams, 
	width: 800,
	height: 800,
	afterClose: () => {
		window[table].reload()
	},
});
